document.script:
// Purchase MIS v2 — Pending pipeline, ageing, who needs to act, stock-out risk, price increases.
// Data is read live with the viewer's permissions. Rules live in CFG below.
const R = root_element;
const Q = (id) => R.querySelector(`[data-id="${id}"]`);
const CFG = {
  stageTypes: ['Material Request', 'Purchase Commercial Approval', 'Purchase Order', 'Quality Inspection', 'Purchase Receipt'],
  limits: { // time limits agreed per stage (same text as the ERP assignments)
    'Material Request': 'RFQ 2 d · PO 7 d',
    'Purchase Commercial Approval': '1 working day',
    'Purchase Order': 'PO required-by date',
    'Quality Inspection': '2 days from receipt',
    'Purchase Receipt': 'Bill in 7 d · escalate 15 d'
  },
  taskLabel: {
    'Material Request': ['Raise RFQ / PO', '1 · Waiting for PO'],
    'Purchase Commercial Approval': ['Decide rate approval', '2 · Approval'],
    'Purchase Order': ['Get material delivered', '3 · Delivery'],
    'Quality Inspection': ['Accept / reject lot', '4 · QC review'],
    'Purchase Receipt': ['Book supplier bill', '5 · Supplier bill']
  },
  mrAgedDays: 30, qcAgedDays: 30, billAgedDays: 60,
  coverDays: 30, coverRows: 8, taskRows: 12, priceRows: 6
};
let AS_OF = frappe.datetime.get_today();
let period = 90, selPerson = null, TASKS = [], showAllTasks = false;

// ---------- helpers ----------
const esc = (s) => frappe.utils.escape_html(String(s == null ? '' : s));
const today = () => AS_OF;
const addDays = (d, n) => frappe.datetime.add_days(d, n);
const diff = (a, b) => frappe.datetime.get_diff(a, b);
const dfmt = (d) => d ? frappe.datetime.str_to_user(d).replace(/-\d{4}$/, '') : '';
function inr(v) {
  v = v || 0; const a = Math.abs(v);
  if (a >= 1e7) return '₹' + (v / 1e7).toFixed(2) + ' Cr';
  if (a >= 1e5) return '₹' + (v / 1e5).toFixed(a >= 1e6 ? 1 : 2).replace(/\.0$/, '') + ' L';
  return '₹' + Math.round(v).toLocaleString('en-IN');
}
const num = (v) => Math.round(v || 0).toLocaleString('en-IN');
function gl(doctype, filters, fields, parent, order_by) {
  return frappe.call({ method: 'frappe.client.get_list', args: { doctype, parent, filters, fields, order_by, limit_page_length: 0 } })
    .then(r => r.message || []);
}
function chunks(arr, n = 400) { const o = []; for (let i = 0; i < arr.length; i += n) o.push(arr.slice(i, i + n)); return o; }
async function glIn(doctype, field, values, extra, fields, parent) {
  if (!values.length) return [];
  const parts = await Promise.all(chunks(values).map(v => gl(doctype, [[field, 'in', v]].concat(extra || []), fields, parent)));
  return parts.flat();
}
const tip = Q('tip');
function hov(el, html) {
  el.addEventListener('mousemove', e => { tip.innerHTML = html; tip.style.opacity = 1; tip.style.left = Math.min(e.clientX + 12, innerWidth - 290) + 'px'; tip.style.top = (e.clientY + 14) + 'px'; });
  el.addEventListener('mouseleave', () => tip.style.opacity = 0);
}
function fail(id, e) { const el = Q(id); if (el) el.innerHTML = `<div class="err">Couldn't load: ${esc(e && (e.message || e))}</div>`; console.error('Purchase MIS', id, e); }
const go = (...a) => frappe.set_route(...a);

// Recorded native base values are authority; never infer a replacement FX rate.
function fxMul() { return 1; }

// ---------- ring ----------
function ring(segs, total, label) {
  const r = 22, c = 2 * Math.PI * r; let off = 0, arcs = '';
  segs.forEach(([v, col]) => { if (!v || !total) return; const len = v / total * c; arcs += `<circle cx="28" cy="28" r="${r}" fill="none" stroke="${col}" stroke-width="7" stroke-dasharray="${Math.max(len - 2, 1)} ${c}" stroke-dashoffset="${-off}" transform="rotate(-90 28 28)"/>`; off += len; });
  return `<svg class="ring" width="56" height="56" viewBox="0 0 56 56" aria-hidden="true"><circle cx="28" cy="28" r="${r}" fill="none" stroke="var(--soft)" stroke-width="7"/>${arcs}<text x="28" y="32" text-anchor="middle" font-size="11.5" font-weight="650" fill="var(--ink)">${label}</text></svg>`;
}
const pct = (a, b) => b ? Math.round(a / b * 100) + '%' : '—';

// ---------- data ----------
async function stageMR() {
  const mr = await gl('Material Request', [['docstatus', '=', 1], ['material_request_type', '=', 'Purchase'], ['status', 'not in', ['Stopped', 'Cancelled', 'Ordered', 'Received', 'Issued', 'Transferred']]], ['name', 'transaction_date']);
  const mrd = {}; mr.forEach(m => mrd[m.name] = m);
  const items = (await glIn('Material Request Item', 'parent', mr.map(m => m.name), [], ['parent', 'item_code', 'stock_qty', 'ordered_qty', 'schedule_date', 'name'], 'Material Request'))
    .filter(i => (i.ordered_qty || 0) < (i.stock_qty || 0) - 1e-6);
  const rfq = await glIn('Request for Quotation Item', 'material_request_item', items.map(i => i.name), [['docstatus', '<', 2]], ['material_request_item'], 'Request for Quotation');
  const inRfq = new Set(rfq.map(r => r.material_request_item));
  const codes = [...new Set(items.map(i => i.item_code))];
  const poi = await glIn('Purchase Order Item', 'item_code', codes, [['docstatus', '=', 1]], ['item_code', 'base_rate', 'conversion_factor', 'parent', 'creation'], 'Purchase Order');
  const pos = await glIn('Purchase Order', 'name', [...new Set(poi.map(p => p.parent))], [], ['name', 'currency', 'conversion_rate', 'transaction_date']);
  const pm = {}; pos.forEach(p => pm[p.name] = p);
  const last = {};
  poi.filter(p => pm[p.parent]).sort((a, b) => (pm[a.parent].transaction_date + a.creation) < (pm[b.parent].transaction_date + b.creation) ? -1 : 1).forEach(p => last[p.item_code] = p);
  let value = 0, priced = 0;
  items.forEach(i => { const p = last[i.item_code]; if (!p) return; const P = pm[p.parent]; const r = p.base_rate / (p.conversion_factor || 1) * fxMul(P.currency, P.conversion_rate); i.exposure = r * (i.stock_qty - i.ordered_qty); value += i.exposure; priced++; });
  const t = today();
  const aged = items.filter(i => diff(t, mrd[i.parent].transaction_date) >= CFG.mrAgedDays).length;
  return { lines: items.length, value, priced, inRfq: items.filter(i => inRfq.has(i.name)).length, aged, rows: items.map(i => ({document:i.parent, detail:i.name, item:i.item_code, quantity:i.stock_qty-i.ordered_qty, value:i.exposure == null ? null : i.exposure})) };
}
async function stagePCA() {
  return frappe.call({ method: 'calco_erp.holistic_ui.purchase_mis.commercial_approval_sla', args: { period } }).then(r => r.message);
}
async function stagePO() {
  const pos = await gl('Purchase Order', [['docstatus', '=', 1], ['status', 'not in', ['Closed', 'Completed', 'Cancelled', 'Delivered', 'On Hold']]], ['name', 'currency', 'conversion_rate']);
  const pm = {}; pos.forEach(p => pm[p.name] = p);
  const it = await frappe.call({ method: 'calco_erp.holistic_ui.purchase_mis.pending_po_lines', args: {} }).then(r => r.message);
  const t = today(), wk = addDays(t, 7);
  const b = { o: [0, 0], n: [0, 0], l: [0, 0] }, late = [[0, 0], [0, 0], [0, 0], [0, 0]]; let tot = 0; const ps = new Set();
  it.forEach(i => {
    const P = pm[i.parent] || i; const v = i.base_rate * fxMul(P.currency, P.conversion_rate) * (i.qty - i.received_qty); tot += v; ps.add(i.parent);
    const k = i.schedule_date < t ? 'o' : i.schedule_date <= wk ? 'n' : 'l'; b[k][0] += v; b[k][1]++;
    if (k === 'o') { const d = diff(t, i.schedule_date); const j = d <= 7 ? 0 : d <= 30 ? 1 : d <= 60 ? 2 : 3; late[j][0] += v; late[j][1]++; }
  });
  const rate1 = pos.filter(p => p.currency !== 'INR' && p.conversion_rate == 1).length;
  return { lines: it.length, pos: ps.size, tot, b, late, rate1, rows: it.map(i => ({document:i.parent, detail:i.detail, item:i.item_code, quantity:i.qty-i.received_qty, value:i.base_rate*(i.qty-i.received_qty)})) };
}
async function stageQC() {
  const qi = await gl('Quality Inspection', [['reference_type', '=', 'Purchase Receipt'], ['status', '=', 'Review Required'], ['inspection_type', '=', 'Incoming'], ['docstatus', '<', 2]], ['name', 'report_date', 'creation']);
  const t = today();
  const d0 = q => q.report_date || q.creation.slice(0, 10);
  return { n: qi.length, aged: qi.filter(q => diff(t, d0(q)) >= CFG.qcAgedDays).length, recent: qi.filter(q => diff(t, d0(q)) <= 3).length, rows: qi.map(i => ({document:i.name, date:d0(i)})) };
}
async function stageBill() {
  const pr = await gl('Purchase Receipt', [['docstatus', '=', 1], ['is_return', '=', 0], ['per_billed','<',100], ['status', 'in', ['To Bill', 'Partly Billed']]], ['name', 'posting_date', 'base_grand_total', 'per_billed', 'currency', 'conversion_rate']);
  const t = today(); const b = [[0, 0], [0, 0], [0, 0], [0, 0]]; let tot = 0;
  pr.forEach(p => { const v = p.base_grand_total * (1 - (p.per_billed || 0) / 100) * fxMul(p.currency, p.conversion_rate); p.exposure = v; tot += v; const d = diff(t, p.posting_date); const j = d <= 15 ? 0 : d <= 30 ? 1 : d <= 60 ? 2 : 3; b[j][0] += v; b[j][1]++; });
  const pi = await gl('Purchase Invoice', [['docstatus', '=', 0]], ['base_grand_total']);
  return { n: pr.length, tot, b, aged: b[3][1], agedV: b[3][0], draft: pi.length, draftV: pi.reduce((a, x) => a + (x.base_grand_total || 0), 0), rows: pr.map(i => ({document:i.name, date:i.posting_date, value:i.exposure})) };
}
async function loadTodos() {
  const td = await gl('ToDo', [['status', '=', 'Open'], ['reference_type', 'in', CFG.stageTypes]], ['name', 'reference_type', 'reference_name', 'allocated_to', 'date', 'description']);
  const users = await glIn('User', 'name', [...new Set(td.map(x => x.allocated_to).filter(Boolean))], [], ['name', 'full_name']);
  const un = {}; users.forEach(u => un[u.name] = (u.full_name || u.name).toLowerCase());
  // one line of context per document
  const by = (t) => [...new Set(td.filter(x => x.reference_type === t).map(x => x.reference_name))];
  const ctx = {};
  const put = (rows, key, f) => rows.forEach(r => ctx[key + '|' + r.name] = f(r));
  put(await glIn('Purchase Order', 'name', by('Purchase Order'), [], ['name', 'supplier_name']), 'Purchase Order', r => r.supplier_name);
  put(await glIn('Purchase Receipt', 'name', by('Purchase Receipt'), [], ['name', 'supplier_name']), 'Purchase Receipt', r => r.supplier_name);
  put(await glIn('Quality Inspection', 'name', by('Quality Inspection'), [], ['name', 'item_code', 'item_name']), 'Quality Inspection', r => r.item_name || r.item_code);
  put(await glIn('Purchase Commercial Approval', 'name', by('Purchase Commercial Approval'), [], ['name', 'item_code', 'supplier']), 'Purchase Commercial Approval', r => r.item_code + ' · ' + (r.supplier || ''));
  put(await glIn('Material Request', 'name', by('Material Request'), [], ['name', 'title']), 'Material Request', r => r.title || '');
  const t = today();
  return td.map(x => ({ ...x, who: un[x.allocated_to] || x.allocated_to || 'Unassigned', late: x.date ? diff(t, x.date) : null, ctx: ctx[x.reference_type + '|' + x.reference_name] || '' }));
}

// Drill-through uses exactly the complete rows used by the rendered card.
function showPipelineRows(doctype, rows, stage, asof) {
  const hasValue = rows.some(r => Object.hasOwn(r, 'value'));
  const total = rows.reduce((v,r) => v + (r.value || 0), 0);
  const columns = ['document','detail','item','quantity','date','due_date','status'].filter(k => rows.some(r => r[k] != null));
  if (hasValue) columns.push('value');
  const dialog = new frappe.ui.Dialog({title: `${doctype}: ${rows.length} matching ${['mr','po'].includes(stage) ? 'lines' : 'records'}`, size:'extra-large', fields:[{fieldname:'rows',fieldtype:'HTML'}]});
  const html = `<p>As of ${esc(asof)} · same complete population as the pipeline card${hasValue ? ` · ${inr(total)}${stage==='mr' ? ' estimated from recorded PO rates; unpriced lines shown blank' : ''}` : ''}</p><div style="overflow:auto;max-height:65vh"><table class="table table-bordered"><thead><tr>${columns.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr>${columns.map(k=>`<td>${k==='document' ? `<button class="btn btn-link" data-row="${i}">${esc(r[k])}</button>` : esc(r[k] == null ? '' : r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  dialog.fields_dict.rows.$wrapper.html(html);
  dialog.fields_dict.rows.$wrapper.find('[data-row]').on('click', function() {const row=rows[Number(this.dataset.row)];dialog.hide();go('Form',doctype,row.document);});
  dialog.show();
}

// ---------- render: pipeline ----------
function ownerOf(type) {
  const c = {}; TASKS.filter(t => t.reference_type === type).forEach(t => c[t.who] = (c[t.who] || 0) + 1);
  const top = Object.entries(c).sort((a, b) => b[1] - a[1])[0];
  return top ? top[0] : '—';
}
function renderFlow(s) {
  const [mr, pca, po, qc, bill] = s;
  const st = [
    { n: 1, t: 'Waiting for PO', type: 'Material Request', big: mr.lines, unit: 'MR lines', val: '≈ ' + inr(mr.value) + ' at latest PO rate',
      note: `${mr.inRfq} already in RFQ · ${mr.lines - mr.inRfq} without an RFQ`, segs: [[mr.aged, 'var(--warn)'], [mr.lines - mr.aged, 'var(--s1)']], tot: mr.lines,
      flag: mr.aged ? ['warn', `◷ ${mr.aged} waiting ${CFG.mrAgedDays}+ days`] : ['good', '✓ None waiting 30+ days'], tipx: `${mr.aged} of ${mr.lines} MR lines waiting ${CFG.mrAgedDays}+ days`,
      route: () => showPipelineRows('Material Request', mr.rows, 'mr', AS_OF) },
    { n: 2, t: 'Commercial approval', type: 'Purchase Commercial Approval', big: pca.pending, unit: 'pending', val: `${pca.decided} decided in ${period} days`,
      note: `${pca.approved} approved · ${pca.rejected} rejected`, segs: [[pca.late, 'var(--warn)'], [pca.pending - pca.late, 'var(--s1)']], tot: pca.pending,
      flag: pca.unknown ? ['warn', `${pca.unknown} SLA dates require review`] : pca.pending ? (pca.late ? ['warn', `◷ ${pca.late} overdue under approved working-day SLA`] : ['good', '✓ Within approved SLA']) : ['good', '✓ Nothing pending'], tipx: `${pca.late} overdue · ${pca.unknown} dates require review · approved calendar policy`,
      route: () => showPipelineRows('Purchase Commercial Approval', pca.rows, 'pca', AS_OF) },
    { n: 3, t: 'Awaiting delivery', type: 'Purchase Order', big: po.lines, unit: 'PO lines', val: inr(po.tot),
      note: `${po.pos} POs · ${po.b.n[1]} lines (${inr(po.b.n[0])}) due in the next 7 days`, segs: [[po.b.o[1], 'var(--crit)'], [po.b.n[1], 'var(--s1)'], [po.b.l[1], 'var(--s2)']], tot: po.lines, mstack: po.b,
      flag: po.b.o[1] ? ['crit', `◷ ${po.b.o[1]} overdue · ${inr(po.b.o[0])}`] : ['good', '✓ Nothing overdue'],
      tipx: `Overdue ${inr(po.b.o[0])} (${po.b.o[1]}) · Next 7 days ${inr(po.b.n[0])} (${po.b.n[1]}) · Later ${inr(po.b.l[0])} (${po.b.l[1]})`,
      route: () => showPipelineRows('Purchase Order', po.rows, 'po', AS_OF) },
    { n: 4, t: 'QC review open', type: 'Quality Inspection', big: qc.n, unit: 'incoming lots', val: 'Status: Review Required',
      note: `${qc.recent} raised in the last 3 days`, segs: [[qc.aged, 'var(--warn)'], [qc.n - qc.aged, 'var(--s1)']], tot: qc.n,
      flag: qc.aged ? ['warn', `◷ ${qc.aged} open for ${CFG.qcAgedDays}+ days`] : ['good', '✓ None open 30+ days'], tipx: `${qc.aged} of ${qc.n} lots open ${CFG.qcAgedDays}+ days`,
      route: () => showPipelineRows('Quality Inspection', qc.rows, 'qc', AS_OF) },
    { n: 5, t: 'Awaiting supplier bill', type: 'Purchase Receipt', big: bill.n, unit: 'GRNs', val: inr(bill.tot),
      note: `${bill.draft} purchase invoices in draft (${inr(bill.draftV)})`, segs: [[bill.aged, 'var(--warn)'], [bill.n - bill.aged, 'var(--s1)']], tot: bill.n,
      flag: bill.aged ? ['warn', `◷ ${bill.aged} older than ${CFG.billAgedDays} days`] : ['good', '✓ None older than 60 days'], tipx: `${bill.aged} of ${bill.n} GRNs older than ${CFG.billAgedDays} days`,
      route: () => showPipelineRows('Purchase Receipt', bill.rows, 'bill', AS_OF) }
  ];
  const flow = Q('flow'); flow.innerHTML = '';
  st.forEach(s => {
    const aged = s.segs[0][0];
    const d = document.createElement('div'); d.className = 'stage'; d.title = 'Open exact counted rows';
    const ms = s.mstack ? `<div class="mstack"><div style="flex:${s.mstack.o[0] || 0};background:var(--crit)"></div><div style="flex:${s.mstack.n[0] || 0};background:var(--s1)"></div><div style="flex:${s.mstack.l[0] || 0};background:var(--s2)"></div></div>` : '';
    d.innerHTML = `<div class="hd"><span class="no">${s.n}</span>${s.t}</div>
      <div class="body">${ring(s.segs, s.tot, s.tot ? pct(aged, s.tot) : '—')}<div><div class="big">${num(s.big)}</div><div class="unit">${s.unit}</div></div></div>
      <div class="val">${s.val}</div>${ms}<div class="note">${s.note}</div>
      <div class="flag ${s.flag[0]}">${s.flag[1]}</div>
      <div class="owner"><span>Owner <b>${esc(ownerOf(s.type))}</b></span><span>Limit <b>${esc(CFG.limits[s.type])}</b></span></div>`;
    hov(d.querySelector('.ring'), `<b>${s.t}</b><br>${s.tipx}`);
    d.onclick = s.route;
    flow.appendChild(d);
  });
}
function ages(id, rows) {
  const mx = Math.max(...rows.map(r => r[1]), 1); const el = Q(id); el.innerHTML = '';
  rows.forEach(([k, v, n], i) => {
    const r = document.createElement('div'); r.className = 'age';
    r.innerHTML = `<div class="k">${k}</div><div class="tr"><div class="f" style="width:${v / mx * 100}%;background:var(--a${i + 1})"></div></div><div class="v"><b>${inr(v)}</b> · ${n}</div>`;
    hov(r.querySelector('.tr'), `<b>${k}</b><br>${inr(v)} · ${n} lines`); el.appendChild(r);
  });
}
function renderAges(po, bill) {
  const L = po.late, n = L.reduce((a, x) => a + x[1], 0), v = L.reduce((a, x) => a + x[0], 0);
  Q('ageDelDesc').textContent = `Pending value · ${n} PO lines past the required-by date`;
  ages('ageDel', [['1–7 days', ...L[0]], ['8–30 days', ...L[1]], ['31–60 days', ...L[2]], ['Over 60 days', ...L[3]]]);
  const bi = L.reduce((bi, x, i) => x[0] > L[bi][0] ? i : bi, 0), names = ['1–7', '8–30', '31–60', 'over 60'];
  Q('ageDelFoot').innerHTML = n ? `<b>${L[bi][1]} of ${n}</b> overdue lines are ${names[bi]} days late, carrying <b>${Math.round(L[bi][0] / v * 100)}%</b> of the overdue value.` : '';
  const B = bill.b;
  Q('ageBillDesc').textContent = `Receipt value · ${bill.n} GRNs not yet billed`;
  ages('ageBill', [['0–15 days', ...B[0]], ['16–30 days', ...B[1]], ['31–60 days', ...B[2]], ['Over 60 days', ...B[3]]]);
  Q('ageBillFoot').innerHTML = B[3][1] ? `<b>${B[3][1]} GRNs worth ${inr(B[3][0])}</b> are more than 60 days old with no purchase invoice.` : '';
}
function renderFxChip(po) {
  const c = Q('fxchip'); if (!c) return;
  c.hidden = !po.rate1;
  c.textContent = `⚠ ${po.rate1} foreign POs have recorded rate 1 · recorded base values retained; Accounts review required`;
}

// ---------- render: people ----------
function renderPeople() {
  const pe = Q('people'); pe.innerHTML = '';
  if (!TASKS.length) { pe.innerHTML = '<div class="loading">No open purchase assignments.</div>'; renderTasks(); return; }
  const agg = {};
  TASKS.forEach(t => { const a = agg[t.who] = agg[t.who] || { v: [0, 0, 0], types: new Set() }; a.v[t.late == null ? 2 : t.late > 0 ? 0 : t.late >= -7 ? 1 : 2]++; a.types.add(CFG.taskLabel[t.reference_type][1].replace(/^\d · /, '')); });
  const rows = Object.entries(agg).sort((a, b) => (b[1].v[0] - a[1].v[0]) || ((b[1].v[0] + b[1].v[1] + b[1].v[2]) - (a[1].v[0] + a[1].v[1] + a[1].v[2])));
  const mx = Math.max(...rows.map(([, a]) => a.v[0] + a.v[1] + a.v[2]));
  rows.forEach(([who, a]) => {
    const tot = a.v[0] + a.v[1] + a.v[2];
    const row = document.createElement('div'); row.className = 'person' + (selPerson === who ? ' on' : '');
    row.innerHTML = `<div><div class="nm">${esc(who)}</div><div class="role">${esc([...a.types].join(' · '))}</div></div><div class="pbar" style="width:${tot / mx * 100}%"></div><div class="tot">${tot}</div>`;
    const pb = row.querySelector('.pbar');
    [['Overdue', 'var(--crit)'], ['Due in 7 days', 'var(--s1)'], ['Later', 'var(--s2)']].forEach(([k, c], i) => { if (!a.v[i]) return; const d = document.createElement('div'); d.style.flex = a.v[i]; d.style.background = c; hov(d, `<b>${esc(who)}</b><br>${k}: ${a.v[i]} tasks`); pb.appendChild(d); });
    row.onclick = () => { selPerson = selPerson === who ? null : who; showAllTasks = false; renderPeople(); };
    pe.appendChild(row);
  });
  renderTasks();
}
function renderTasks() {
  const tb = Q('tasks'); tb.innerHTML = '';
  const list = TASKS.filter(t => !selPerson || t.who === selPerson).sort((a, b) => (b.late ?? -999) - (a.late ?? -999));
  const shown = showAllTasks ? list : list.slice(0, CFG.taskRows);
  shown.forEach(t => {
    const s = t.late == null ? '<span class="pill warn">no date</span>' : t.late > 0 ? `<span class="pill crit">▲ ${t.late} d late</span>` : t.late === 0 ? '<span class="pill warn">due today</span>' : `<span class="pill good">in ${-t.late} d</span>`;
    const [task, stage] = CFG.taskLabel[t.reference_type];
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${task}</td><td class="muted">${stage}</td><td><span class="doc">${esc(t.reference_name)}<small>${esc(t.ctx)}</small></span></td><td style="text-transform:capitalize">${esc(t.who)}</td><td>${dfmt(t.date)}</td><td class="num">${s}</td>`;
    tr.querySelector('.doc').onclick = () => go('Form', t.reference_type, t.reference_name);
    tb.appendChild(tr);
  });
  const more = Q('more');
  more.innerHTML = list.length > CFG.taskRows ? `<button class="btn">${showAllTasks ? 'Show fewer' : `Show all ${list.length} tasks`}</button>` : '';
  if (more.firstChild) more.firstChild.onclick = () => { showAllTasks = !showAllTasks; renderTasks(); };
}

// ---------- render: stock-out ----------
async function loadCover() {
  const r = await frappe.call({ method: 'calco_erp.calco_purchase.page.rm_planning_dashboard.rm_planning_dashboard.get_dashboard_data', args: {} }).then(r => r.message);
  const rows = (r.rows || []).filter(x => x.selected_daily_consumption > 0).map(x => {
    const need = x.selected_daily_consumption * CFG.coverDays, have = (x.available_inventory || 0) + (x.open_po_in_transit_qty || 0);
    return { c: x.item_code, n: x.item_name, need, have, stock: x.available_inventory || 0, po: x.open_po_in_transit_qty || 0, mr: x.open_material_request_qty || 0, u: x.stock_uom || '', p: Math.round(have / need * 100), daily: x.selected_daily_consumption };
  }).sort((a, b) => a.p - b.p);
  const short = rows.filter(x => x.p < 100);
  const el = Q('cover'); el.innerHTML = '';
  el.insertAdjacentHTML('beforeend', `<div class="coversum"><b>${short.length} of ${rows.length}</b> raw materials in use won't cover the next ${CFG.coverDays} days${short.filter(x => x.p < 70).length ? ` · <b>${short.filter(x => x.p < 70).length}</b> below 70%` : ''}.</div>`);
  rows.slice(0, CFG.coverRows).forEach(x => {
    const col = x.p < 70 ? 'var(--crit)' : x.p < 100 ? 'var(--warn)' : 'var(--good)';
    const lab = x.p < 70 ? `<span class="pill crit">⚠ ${x.p}%</span>` : x.p < 100 ? `<span class="pill warn">! ${x.p}%</span>` : `<span class="pill good">✓ ${x.p}%</span>`;
    const row = document.createElement('div'); row.className = 'ci';
    row.innerHTML = `<div class="nm">${esc(x.c)}<small>${esc(x.n)}</small></div><div class="tr"><div class="fill" style="width:${Math.min(x.p, 200) / 2}%;background:${col}"></div><div class="needl" style="left:50%"></div></div><div class="val2">${lab}</div>`;
    hov(row.querySelector('.tr'), `<b>${esc(x.c)}</b><br>Need ${num(x.need)} ${x.u} (${num(x.daily)}/day)<br>Stock ${num(x.stock)} + open PO ${num(x.po)} = ${num(x.have)}<br>MR not yet ordered: ${num(x.mr)} ${x.u}`);
    el.appendChild(row);
  });
}

// ---------- render: prices ----------
// Approval rates have an explicit stored benchmark basis. Supplier-specific
// rates are quotation-currency amounts; legacy benchmark sources are base rates.
// Missing/foreign-company basis is held rather than labelled INR or guessed.
function approvalBaseRows(rows, quotes, companies) {
  const qm=Object.fromEntries(quotes.map(q=>[q.name,q]));
  const cm=Object.fromEntries(companies.map(c=>[c.name,c.default_currency]));
  const baseSources=new Set(['Last Purchase Rate','Average of Last 3 Purchase Orders','Item Standard Buying Rate']);
  let review=0; const resolved=[];
  rows.forEach(row=>{
    const q=qm[row.supplier_quotation];
    if (!q || q.docstatus!==1 || cm[q.company]!=='INR') {review++;return;}
    let factor;
    if (row.benchmark_source==='Supplier-specific Last Purchase Price') factor=Number(q.conversion_rate);
    else if (baseSources.has(row.benchmark_source)) factor=1;
    if (!(factor>0)) {review++;return;}
    resolved.push({...row,quoted_rate:row.quoted_rate*factor,benchmark_rate:row.benchmark_rate*factor});
  });
  return {rows:resolved,review};
}

async function loadPrices() {
  const from = addDays(today(), -period);
  const raw = await gl('Purchase Commercial Approval', [['approval_status', '=', 'Approved'], ['docstatus','<',2], ['approval_date', '>=', from]], ['item_code', 'item_name', 'supplier', 'qty', 'benchmark_rate', 'quoted_rate', 'reason_for_higher_price', 'approval_date', 'supplier_quotation', 'benchmark_source']);
  const quotes = await glIn('Supplier Quotation','name',[...new Set(raw.map(r=>r.supplier_quotation).filter(Boolean))],[],['name','company','docstatus','conversion_rate']);
  const companies = await glIn('Company','name',[...new Set(quotes.map(q=>q.company))],[],['name','default_currency']);
  const basis = approvalBaseRows(raw,quotes,companies), p=basis.rows;
  const withB = p.filter(x => x.benchmark_rate > 0 && x.quoted_rate > 0);
  const above = withB.filter(x => x.quoted_rate > x.benchmark_rate && x.quoted_rate / x.benchmark_rate < 2);
  const broken = withB.filter(x => x.quoted_rate / x.benchmark_rate >= 2 || x.quoted_rate / x.benchmark_rate <= 0.5).length;
  const extra = above.reduce((a, x) => a + (x.quoted_rate - x.benchmark_rate) * x.qty, 0);
  const okOnly = above.filter(x => /^\s*ok\.?\s*$/i.test(x.reason_for_higher_price || '') || !(x.reason_for_higher_price || '').trim()).length;
  const g = {};
  above.forEach(x => { const k = x.item_code + '|' + x.supplier; const o = g[k] = g[k] || { i: x.item_code, nm: x.item_name, s: x.supplier, ex: 0, n: 0, b: x.benchmark_rate, q: x.quoted_rate, qty: 0, d: x.approval_date };
    o.ex += (x.quoted_rate - x.benchmark_rate) * x.qty; o.n++; o.qty += x.qty; if (x.approval_date >= o.d) { o.d = x.approval_date; o.b = x.benchmark_rate; o.q = x.quoted_rate; } });
  const top = Object.values(g).sort((a, b) => b.ex - a.ex).slice(0, CFG.priceRows);
  Q('priceDesc').innerHTML = `Last ${period} days · recorded approval basis converted at recorded quotation rate · ${basis.review} require currency/basis review${broken ? ` · ${broken} with a broken benchmark left out` : ''}`;
  const el = Q('prices'); el.innerHTML = '';
  el.insertAdjacentHTML('beforeend', `<div class="pricesum"><span><b>${above.length}</b>approved above last rate</span><span><b>${inr(extra)}</b>approved rate variance</span><span><b>${okOnly} of ${above.length}</b>gave no real reason</span></div>`);
  if (!top.length) { el.insertAdjacentHTML('beforeend', '<div class="loading">No approvals above the last rate in this period.</div>'); return; }
  const mx = Math.max(...top.map(t => (t.q / t.b - 1) * 100), 5);
  top.forEach(t => {
    const pc = (t.q / t.b - 1) * 100;
    const d = document.createElement('div'); d.className = 'pr';
    d.innerHTML = `<div class="nm">${esc(t.i)}<small>${esc(t.s)}</small></div><div><div class="bar" style="width:${pc / mx * 100}%"></div><div class="meta">+${pc.toFixed(1)}% · ₹${t.b} → ₹${t.q}${t.n > 1 ? ` · ${t.n} approvals` : ''}</div></div><div class="x">${inr(t.ex)}</div>`;
    hov(d.querySelector('.bar'), `<b>${esc(t.i)}</b> · ${esc(t.s)}<br>${esc(t.nm || '')}<br>₹${t.b} → ₹${t.q} (+${pc.toFixed(1)}%)<br>Qty ${num(t.qty)} · extra ${inr(t.ex)}`);
    el.appendChild(d);
  });
}

// ---------- main ----------
async function loadAll() {
  AS_OF = frappe.datetime.get_today();
  Q('asof').textContent = `As of ${frappe.datetime.str_to_user(today())} · pipeline is live · approvals and prices: last ${period} days`;
  const todoP = loadTodos().then(t => { TASKS = t; renderPeople(); }).catch(e => fail('people', e));
  const stagesP = Promise.all([stageMR(), stagePCA(), stagePO(), stageQC(), stageBill()]);
  try {
    const s = await stagesP; await todoP;
    renderFlow(s); renderAges(s[2], s[4]); renderFxChip(s[2]);
  } catch (e) { fail('flow', e); fail('ageDel', e); fail('ageBill', e); }
  loadCover().catch(e => fail('cover', e));
  loadPrices().catch(e => fail('prices', e));
}
Q('period').onchange = (e) => { period = +e.target.value; loadAll(); };
Q('refresh').onclick = () => loadAll();
Q('pending').onclick = Q('pending2').onclick = () => go('query-report', 'Pending Purchase');
Q('todoAll').onclick = () => go('List', 'ToDo', { status: 'Open', reference_type: ['in', CFG.stageTypes] });
Q('rmplan').onclick = () => go('rm-planning-dashboard');
Q('pca').onclick = () => go('List', 'Purchase Commercial Approval');
loadAll();

