frappe.query_reports["Pending Purchase"] = {
	filters: [
		{ fieldname: "from_date", label: __("From Date"), fieldtype: "Date", default: frappe.datetime.month_start(), reqd: 1 },
		{ fieldname: "to_date", label: __("To Date"), fieldtype: "Date", default: frappe.datetime.month_end(), reqd: 1 },
		{ fieldname: "based_on", label: __("Date Based On"), fieldtype: "Select", options: "Document Date\nRequired By Date", default: "Document Date", reqd: 1,
			description: __("Document Date = MR date for Awaiting PO, PO date for Awaiting Delivery") },
		{ fieldname: "stage", label: __("Stage"), fieldtype: "Select", options: "All\nAwaiting PO\nAwaiting Delivery", default: "All", reqd: 1 }
	],
	formatter: function (value, row, column, data, default_formatter) {
		if (!data && ["rate", "days_overdue"].includes(column.fieldname)) return "";
		let out = default_formatter(value, row, column, data);
		if (!data) return out;
		if (column.fieldname === "stage") {
			const color = value === "Awaiting PO" ? "orange" : "blue";
			return "<span class=\"indicator-pill " + color + "\">" + value + "</span>";
		}
		if (column.fieldname === "days_overdue" && value > 0) {
			return "<span style=\"color: var(--red-600); font-weight: 600;\">" + out + "</span>";
		}
		if (data.stage === "Awaiting PO" && ["rate", "pending_value"].includes(column.fieldname)) {
			return "<span style=\"color: var(--text-muted);\" title=\"" + __("Estimated at the item's last purchase rate") + "\">" + out + "</span>";
		}
		return out;
	}
};
